import java.awt.FlowLayout; import java.awt.event.ActionListener; import javax.swing.*;
public class Converter extends JFrame {private final JTextField amount=new JTextField(10);private final JComboBox<String> target=new JComboBox<>(new String[]{"USD","EUR"});private final JLabel result=new JLabel(" ");private static double rate(String c){return c.equals("USD")?.012:.011;}
 public ConverterLambdaCompleteCode(){super("Currency Converter");setLayout(new FlowLayout());JButton convertButton=new JButton("Convert");add(new JLabel("INR"));add(amount);add(target);add(convertButton);add(result);ActionListener listener=e->convert();convertButton.addActionListener(listener);amount.addActionListener(listener);setDefaultCloseOperation(EXIT_ON_CLOSE);pack();}
 private void convert(){try{double n=Double.parseDouble(amount.getText().trim());if(!Double.isFinite(n)||n<0)throw new NumberFormatException();String value=String.format("%.2f",n*rate((String)target.getSelectedItem()));result.setText(value);JOptionPane.showMessageDialog(this,value+" "+target.getSelectedItem());}catch(NumberFormatException e){result.setText("Invalid amount");JOptionPane.showMessageDialog(this,"Invalid amount","Error",JOptionPane.ERROR_MESSAGE);}}
 public static void main(String[]args){SwingUtilities.invokeLater(()->new Converter().setVisible(true));}}
